insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-ek-251","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For 2A → products, $k = 0.50\\ \\mathrm{L\\ mol^{-1}\\ min^{-1}}$ and $[\\mathrm{A}]_0 = 0.20\\ \\mathrm{M}$. The half-life is","options":["10 min","1.4 min","0.10 min","20 min"],"answer_index":0,"explanation":"$t_{1/2} = 1/(k[\\mathrm{A}]_0) = 1/(0.50 \\times 0.20) = 10\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-252","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order isomerisation has $t_{1/2} = 20\\ \\mathrm{min}$. The time required for 87.5% conversion is","options":["60 min","40 min","20 min","80 min"],"answer_index":0,"explanation":"87.5% converted leaves 12.5% = $1/8$, which is three half-lives: $3 \\times 20 = 60\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-253","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Half-life of a gaseous decay is 40 min at 0.80 bar initial pressure and 80 min at 0.40 bar. The order and $k$ (from the 0.80 bar run, treating concentration as proportional to $p$) are consistent with","options":["second order, because $t_{1/2}$ doubles when $p_0$ is halved","first order, because $t_{1/2}$ is independent of $p_0$","zero order, because $t_{1/2}$ halves when $p_0$ is halved","third order, because $t_{1/2} \\propto p_0^2$"],"answer_index":0,"explanation":"Second-order $t_{1/2} \\propto 1/[\\mathrm{A}]_0$. Halving the initial pressure doubles the half-life, which matches the data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-254","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order hydrolysis has $k = 2.303 \\times 10^{-3}\\ \\mathrm{s^{-1}}$. The percentage of reactant still left after 1000 s is nearest","options":["10%","50%","1%","90%"],"answer_index":0,"explanation":"$\\log([\\mathrm{A}]_0/[\\mathrm{A}]) = kt/2.303 = 1.00$, so $[\\mathrm{A}]/[\\mathrm{A}]_0 = 0.10$ (10% remains).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-255","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Activation energy $E_a$ of a reaction is the","options":["minimum extra energy that colliding molecules must possess if they are to react","heat released when products form","same quantity as $\\Delta H$ of the reaction","Faraday constant multiplied by $T$"],"answer_index":0,"explanation":"$E_a$ is the barrier height on the reaction profile. Only collisions that clear that barrier can form products.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-256","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a typical activated reaction, raising the temperature causes the rate constant to","options":["increase","decrease toward zero","become equal to the Faraday constant","lose its units"],"answer_index":0,"explanation":"The Boltzmann factor $e^{-E_a/RT}$ grows as $T$ grows, so $k$ rises (often steeply).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-257","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A plot of $\\ln k$ versus $1/T$ for an Arrhenius reaction is a straight line whose slope equals","options":["$-E_a/R$","$E_a/R$","$-R/E_a$","$A$"],"answer_index":0,"explanation":"$\\ln k = \\ln A - E_a/RT$, so the slope versus $1/T$ is $-E_a/R$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-258","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In $k = A e^{-E_a/RT}$ the pre-exponential factor $A$ is interpreted as","options":["a frequency (or collision) factor, the value $k$ would have if every collision were successful","the activation energy in joules","the gas constant","the equilibrium constant $K_c$"],"answer_index":0,"explanation":"$A$ absorbs the collision frequency and a steric factor. It has the same units as $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-259","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A catalyst speeds a reaction primarily by","options":["providing an alternative path with a lower activation energy","raising the temperature of the surroundings","increasing $\\Delta G^\\circ$ of the reaction","changing the stoichiometric coefficients"],"answer_index":0,"explanation":"A lower $E_a$ increases the fraction of successful collisions. $\\Delta H$ and the position of equilibrium stay the same.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-260","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Threshold energy in collision theory is","options":["the minimum relative kinetic energy that a collision must have to be potentially reactive","the average kinetic energy of the whole sample","equal to $RT$ at every temperature","the energy of the products minus $E_a$"],"answer_index":0,"explanation":"Molecules that meet with energy below the threshold simply bounce apart; those above it may react if oriented properly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
